function pick(value) {
  switch (true) {
    case value:
      return "A";
    case Boolean(value):
      return "B";
    case value == null:
      return "C";
    default:
      return "D";
  }
}

console.log(pick(true), pick("0"), pick(1));
console.log(pick(undefined), pick(0), pick(NaN));
